ALTER TABLE public.profiles ADD COLUMN IF NOT EXISTS age integer, ADD COLUMN IF NOT EXISTS age_group text, ADD COLUMN IF NOT EXISTS lifestyle text, ADD COLUMN IF NOT EXISTS health_goals text[] NOT NULL DEFAULT '{}', ADD COLUMN IF NOT EXISTS nutritional_status text, ADD COLUMN IF NOT EXISTS selected_plan_slug text REFERENCES public.diet_plans(slug), ADD COLUMN IF NOT EXISTS onboarding_step integer NOT NULL DEFAULT 1, ADD COLUMN IF NOT EXISTS clinical_notes text;
ALTER TABLE public.client_intakes ADD COLUMN IF NOT EXISTS age_group text, ADD COLUMN IF NOT EXISTS lifestyle text, ADD COLUMN IF NOT EXISTS health_goals text[] NOT NULL DEFAULT '{}', ADD COLUMN IF NOT EXISTS nutritional_status text, ADD COLUMN IF NOT EXISTS selected_plan_slug text REFERENCES public.diet_plans(slug);
CREATE OR REPLACE FUNCTION public.save_client_registration(_data jsonb, _step integer, _complete boolean DEFAULT false) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$
DECLARE _uid uuid := auth.uid(); _id uuid; _goals text[]; _conditions text[]; _allergies text[]; _bmi numeric;
BEGIN
 IF _uid IS NULL THEN RAISE EXCEPTION 'Please sign in to save your registration'; END IF;
 IF _step NOT BETWEEN 1 AND 4 THEN RAISE EXCEPTION 'Invalid registration step'; END IF;
 IF length(trim(coalesce(_data->>'full_name',''))) < 2 OR coalesce(_data->>'phone','') !~ '^\d{10}$' OR coalesce(_data->>'email','') !~ '^[^@ ]+@[^@ ]+\.[^@ ]+$' THEN RAISE EXCEPTION 'Check your name, phone and email'; END IF;
 IF (_data->>'age')::integer NOT BETWEEN 1 AND 115 OR (_data->>'height_cm')::numeric NOT BETWEEN 100 AND 230 OR (_data->>'weight_kg')::numeric NOT BETWEEN 30 AND 250 THEN RAISE EXCEPTION 'Check your age, height and weight'; END IF;
 IF _complete AND NOT EXISTS(SELECT 1 FROM diet_plans WHERE slug=_data->>'selected_plan_slug' AND active) THEN RAISE EXCEPTION 'Choose an available diet plan'; END IF;
 SELECT coalesce(array_agg(value),'{}') INTO _goals FROM jsonb_array_elements_text(coalesce(_data->'health_goals','[]'));
 SELECT coalesce(array_agg(value),'{}') INTO _conditions FROM jsonb_array_elements_text(coalesce(_data->'health_conditions','[]'));
 SELECT coalesce(array_agg(value),'{}') INTO _allergies FROM jsonb_array_elements_text(coalesce(_data->'allergies','[]'));
 _bmi := round((_data->>'weight_kg')::numeric / power((_data->>'height_cm')::numeric / 100,2),1);
 INSERT INTO profiles(id,full_name,email,phone,city,gender,age,age_group,height_cm,current_weight_kg,target_weight_kg,activity_level,lifestyle,primary_goal,health_goals,diet_preference,health_conditions,allergies,nutritional_status,selected_plan_slug,onboarding_step,onboarding_complete,clinical_notes)
 VALUES(_uid,trim(_data->>'full_name'),_data->>'email',_data->>'phone',_data->>'city',_data->>'gender',(_data->>'age')::integer,_data->>'age_group',(_data->>'height_cm')::numeric,(_data->>'weight_kg')::numeric,nullif(_data->>'target_weight_kg','')::numeric,_data->>'activity_level',_data->>'lifestyle',_goals[1],_goals,_data->>'diet_preference',_conditions,_allergies,_data->>'nutritional_status',nullif(_data->>'selected_plan_slug',''),_step,_complete,_data->>'notes')
 ON CONFLICT(id) DO UPDATE SET full_name=excluded.full_name,email=excluded.email,phone=excluded.phone,city=excluded.city,gender=excluded.gender,age=excluded.age,age_group=excluded.age_group,height_cm=excluded.height_cm,current_weight_kg=excluded.current_weight_kg,target_weight_kg=excluded.target_weight_kg,activity_level=excluded.activity_level,lifestyle=excluded.lifestyle,primary_goal=excluded.primary_goal,health_goals=excluded.health_goals,diet_preference=excluded.diet_preference,health_conditions=excluded.health_conditions,allergies=excluded.allergies,nutritional_status=excluded.nutritional_status,selected_plan_slug=excluded.selected_plan_slug,onboarding_step=excluded.onboarding_step,onboarding_complete=excluded.onboarding_complete,clinical_notes=excluded.clinical_notes;
 SELECT id INTO _id FROM client_intakes WHERE user_id=_uid ORDER BY created_at DESC LIMIT 1;
 IF _id IS NULL THEN
 INSERT INTO client_intakes(user_id,full_name,phone,email,city,gender,age,height_cm,weight_kg,target_weight_kg,bmi,activity_level,primary_goal,diet_preference,health_conditions,allergies,notes,age_group,lifestyle,health_goals,nutritional_status,selected_plan_slug)
 VALUES(_uid,trim(_data->>'full_name'),_data->>'phone',_data->>'email',_data->>'city',_data->>'gender',(_data->>'age')::integer,(_data->>'height_cm')::numeric,(_data->>'weight_kg')::numeric,nullif(_data->>'target_weight_kg','')::numeric,_bmi,_data->>'activity_level',coalesce(_goals[1],''),_data->>'diet_preference',_conditions,_allergies,_data->>'notes',_data->>'age_group',_data->>'lifestyle',_goals,_data->>'nutritional_status',nullif(_data->>'selected_plan_slug','')) RETURNING id INTO _id;
 ELSE
 UPDATE client_intakes SET full_name=trim(_data->>'full_name'),phone=_data->>'phone',email=_data->>'email',city=_data->>'city',gender=_data->>'gender',age=(_data->>'age')::integer,height_cm=(_data->>'height_cm')::numeric,weight_kg=(_data->>'weight_kg')::numeric,target_weight_kg=nullif(_data->>'target_weight_kg','')::numeric,bmi=_bmi,activity_level=_data->>'activity_level',primary_goal=coalesce(_goals[1],''),diet_preference=_data->>'diet_preference',health_conditions=_conditions,allergies=_allergies,notes=_data->>'notes',age_group=_data->>'age_group',lifestyle=_data->>'lifestyle',health_goals=_goals,nutritional_status=_data->>'nutritional_status',selected_plan_slug=nullif(_data->>'selected_plan_slug','') WHERE id=_id AND user_id=_uid;
 END IF;
 RETURN _id;
END; $$;
REVOKE ALL ON FUNCTION public.save_client_registration(jsonb,integer,boolean) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.save_client_registration(jsonb,integer,boolean) TO authenticated,service_role;